INSERT INTO ranking_stock_items
    (set_id, content_key, format, title, content_fields, ranking_data, narration, source_note, is_active)
VALUES
    ((SELECT id FROM batch_sets WHERE set_code = 'pref-ranking-1'), '011-cake-spend', 'top5-map', 'ケーキ大好き都道府県',
     '{"hook":"スイーツの都は東京？いやいや、1位はまさかのあの県だ！","trivia":"1位の埼玉県は年間9,539円！全国平均7,630円の1.2倍以上だ。2位の高知県8,900円と3位の東京都8,897円は、たった3円差の大接戦。TOP5には関東が3県入ってるぞ。あまいもの好きは関東に多いのかもなあ！","source_display":"総務省 家計調査 2023〜25年平均／二人以上世帯の年間支出（政令市等を世帯数加重で県換算）","result_list":"1位 埼玉県 9,539円\\n2位 高知県 8,900円\\n3位 東京都 8,897円\\n4位 福島県 8,852円\\n5位 栃木県 8,824円","value_prefix":"年間","value_suffix":"円","subtitle":"全国平均は7,630円","bg_motif":"いちごのショートケーキとカットケーキ、湯気の立つ紅茶をあしらった上品な洋菓子のモチーフ"}', '{"entries":[{"rank":1,"pref_code":11,"value":9539},{"rank":2,"pref_code":39,"value":8900},{"rank":3,"pref_code":13,"value":8897},{"rank":4,"pref_code":7,"value":8852},{"rank":5,"pref_code":9,"value":8824}]}', '{"30s":{"intro":"ケーキ大好き都道府県、トップ5！","teaser":"1位はどこだと思う？","r5":"第5位は、栃木県！","r5_comment":"北関東から！","r4":"第4位は、福島県！","r4_comment":"甘党の県だ！","r3":"第3位は、東京都！","r3_comment":"スイーツの都！","r2":"第2位は、高知県！","r2_comment":"まさかの土佐！","r1_call":"さあ第1位、スイーツ王は！","r1_name":"埼玉県ーっ！","closing":"スイーツの王座は、意外にも埼玉だったな！"}}', '出典: 総務省統計局「家計調査 品目別都道府県庁所在市及び政令指定都市ランキング」 / データ年: 2023年（令和５年）～2025年（令和７年）平均 / 取得日: 2026-08-24 / URL: https://www.stat.go.jp/data/kakei/zuhyou/rank09.xlsx
都道府県換算（複数市は世帯数による加重平均）
神奈川県: (横浜市 8834円 × 1045037世帯 + 川崎市 8721円 × 405273世帯 + 相模原市 6985円 × 199569世帯) ÷ 1649879世帯 = 8582.59円 → 8583円（四捨五入）
静岡県: (静岡市 7404円 × 193014世帯 + 浜松市 7331円 × 217761世帯) ÷ 410775世帯 = 7365.30円 → 7365円（四捨五入）
大阪府: (大阪市 7608円 × 679830世帯 + 堺市 7479円 × 230462世帯) ÷ 910292世帯 = 7575.34円 → 7575円（四捨五入）
福岡県: (福岡市 7567円 × 398820世帯 + 北九州市 6706円 × 257406世帯) ÷ 656226世帯 = 7229.27円 → 7229円（四捨五入）', 1);

